<template><div class="order-detail"><div class="status-bar"><div class="status">{{ statusText }}</div></div><div class="address-card" v-if="order"><el-icon><Location/></el-icon><div class="info"><div>{{ order.consignee }} {{ order.phone }}</div><div>{{ order.address }}</div></div></div><div class="goods-card" v-for="item in order.items || []" :key="item.id" @click="$router.push('/product/'+item.goods_id)"><el-image :src="item.image" fit="cover" style="width:80px;height:80px"/><div class="info"><div class="name">{{ item.goods_name }}</div><div class="spec">{{ item.spec }}</div><div class="bottom"><span class="price">¥{{ item.price }}</span><span class="qty">x{{ item.quantity }}</span></div></div></div><div class="amount-card" v-if="order"><div class="row"><span>商品总额</span><span>¥{{ order.goods_amount }}</span></div><div class="row"><span>运费</span><span>¥{{ order.shipping_amount || 0 }}</span></div><div class="row"><span>优惠</span><span>-¥{{ order.discount_amount || 0 }}</span></div><div class="row total"><span>实付</span><span class="price">¥{{ order.total_amount }}</span></div></div><div class="footer" v-if="order && order.status===0"><el-button type="primary" @click="goPay">去支付</el-button></div></div></template><script setup>import{ref,computed,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import request from'@/utils/request';const route=useRoute();const router=useRouter();const order=ref({});const statusText=computed(()=>{const map={0:'待付款',1:'待发货',2:'待收货',3:'已完成',4:'已取消'};return map[order.value.status]||'未知'});const goPay=()=>router.push('/pay/'+order.value.order_no);onMounted(async()=>{const res=await request({url:`/orders/${route.params.id}`});order.value=res.data||{}})</script><style scoped>.order-detail{padding-bottom:60px}.status-bar{background:linear-gradient(135deg,#409eff,#67c23a);color:#fff;padding:30px 20px;font-size:20px;font-weight:bold}.address-card{display:flex;align-items:center;padding:15px;background:#fff;margin:10px;border-radius:8px}.address-card .info{margin-left:10px;flex:1;font-size:14px}.goods-card{display:flex;padding:15px;background:#fff;margin:10px;border-radius:8px}.goods-card .info{margin-left:10px;flex:1}.goods-card .name{font-size:14px;font-weight:500}.goods-card .spec{font-size:12px;color:#909399;margin:5px 0}.goods-card .bottom{display:flex;justify-content:space-between;margin-top:10px}.goods-card .price{color:#f56c6c;font-weight:bold}.amount-card{background:#fff;margin:10px;padding:15px;border-radius:8px}.amount-card .row{display:flex;justify-content:space-between;padding:5px 0;font-size:14px}.amount-card .total{border-top:1px solid #eee;margin-top:10px;padding-top:10px;font-weight:bold}.amount-card .price{color:#f56c6c;font-size:18px}.footer{position:fixed;bottom:0;left:0;right:0;padding:10px 20px;background:#fff;border-top:1px solid #eee;display:flex;justify-content:flex-end}</style>
